// Save scroll position in localStorage
const storageKey = 'scrollPos' + chapter_id; const bookStorageKey = 'bookChapters' + post_id;
function getScrollPercent(scrollTop, contentTop, contentHeight, winHeight) {
    const totalScrollable = contentHeight - winHeight;
    if (totalScrollable <= 0) return 100;
    return Math.round(((scrollTop - contentTop) / totalScrollable) * 100);
}
function cleanScrollPosLocalStorage() {
    localStorage.clear();
}
function updateBookChapters(postId, chapterId) {
    const MAX_CHAPTERS_PER_BOOK = 10;
    const bookKey = `bookChapters${postId}`;
    let chapters = JSON.parse(localStorage.getItem(bookKey)) || [];
    chapters = chapters.filter(id => id !== chapterId);
    chapters.unshift(chapterId);
    if (chapters.length > MAX_CHAPTERS_PER_BOOK) {
        const removedChapters = chapters.splice(MAX_CHAPTERS_PER_BOOK);
        removedChapters.forEach(id => {
            localStorage.removeItem(`scrollPos${id}`);
        });
    }
    try {
        localStorage.setItem(bookKey, JSON.stringify(chapters));
    } catch (e) {
        if (e.name === 'QuotaExceededError' || e.name === 'NS_ERROR_DOM_QUOTA_REACHED') {
            cleanScrollPosLocalStorage()
        }
    }
}
const contentTop = $('#content').offset().top;
const contentHeight = $('#content').outerHeight();
updateBookChapters(post_id, chapter_id);
const savedScroll = localStorage.getItem(storageKey);
if (savedScroll !== null) {
    const scrollTop = parseInt(savedScroll);
    const percent = getScrollPercent(scrollTop, contentTop, contentHeight, $(window).height());
    if (scrollTop > contentTop && percent < 100) {
        $('#scroll-percent').text(`${percent}%`);
        $('#restore-scroll-btn').removeClass('d-none');
    }
}
$('#restore-scroll-btn').on('click', function () {
    $(window).scrollTop(savedScroll);
    $(this).fadeOut();
});

